R=pathlib.Path('.');D='2026-10-26';NOW=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat()
def load(p):return json.loads((R/p).read_text(encoding='utf-8-sig'))
def save(p,x):
 p=R/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
r=load(f'docs/daily-reports/{D}.json');over=load('src/data/i18n/en-overrides.json');photos={p['key']:p for p in load(f'docs/image-licenses/{D}.json')}
def t(a,b):
 over[a]=b
 if a.startswith('#'):over[a.lstrip('# ')]=b.lstrip('# ')
 return a
def photo(k):
 p=photos[k];return dict(image='/'+p['file'].removeprefix('public/'),imageAlt=t({'ca':'Memorial大學校園資料照','uk':'英國教育部倫敦辦公室資料照','au':'坎培拉Dickson College校園資料照','iowa':'Iowa State Beardshear Hall資料照','pfp':'Miami University Upham Hall資料照','ywh':'Miami University MacCracken Hall資料照','diy':'Miami University校園冬季資料照','taiwan':'清華大學校園資料照'}[k],{'ca':'Archive photograph of Memorial University campus','uk':'Archive photograph of the Department for Education office in London','au':'Archive photograph of Dickson College in Canberra','iowa':'Archive photograph of Iowa State Beardshear Hall','pfp':'Archive photograph of Miami University Upham Hall','ywh':'Archive photograph of Miami University MacCracken Hall','diy':'Archive winter photograph of Miami University campus','taiwan':'Archive photograph of National Tsing Hua University campus'}[k]),imageCredit=p['author']+' / '+p['license']+'; cropped',imageSource=p['source'],imageLicense=p['license'])
def md(path,fm,pairs,key):
 p=R/path;assert not p.exists(),path
 p.write_text('---\n'+''.join(k+': '+json.dumps(v,ensure_ascii=False)+'\n' for k,v in fm.items())+'---\n\n'+'\n\n'.join(t(a,b) for a,b in pairs)+f'\n\n[Photo attribution and adaptation license](/images/daily/{D}/credits.html#{key})\n',encoding='utf8')
 for suf,eng in [('｜環球教育新聞網 Global Education News',' | Global Education News'),('｜台灣國際獎學金雷達',' | Taiwan Global Scholarship Radar')]:over[fm['title']+suf]=over[fm['title']]+eng
